  static String achievementTitle(String id, String locale) {
    final key = 'achievement_${id.replaceAll('-', '_')}';
    final title = t(key, locale);
    return title == key ? id : title;
  }

  /// Localized level label for a total score (display-only; stored level may differ).
  static String levelLabelForTotal(double total, [String locale = 'English']) {
    if (total <= 20) return '${t('level_new_arrival', locale)} 🆕';
    if (total <= 40) return '${t('level_settling_in', locale)} 🏠';
    if (total <= 79) return '${t('level_growing_strong', locale)} 📈';
    if (total <= 94) return '${t('level_established_resident', locale)} 🏆';
    return '${t('level_qatar_pro', locale)} ⭐';
  }
}
